package br.com.confirmacao.user.infrastructure;import br.com.confirmacao.user.domain.User;import org.springframework.data.jpa.repository.JpaRepository;import java.util.*;public interface UserRepository extends JpaRepository<User,UUID>{Optional<User> findByEmailIgnoreCase(String email);boolean existsByEmailIgnoreCase(String email);boolean existsByEmailIgnoreCaseAndIdNot(String email,UUID id);Optional<User> findByProfessionalId(UUID professionalId);}
